Here is a simple JavaScript applet that simulates a pendulum using the HTML5 canvas element. The pendulum's swing is governed by the equation for simple harmonic motion:

ds/dt = sqrt(g/l) * sin(asyst - ωt)

where:
- ds/dt is the derivative of the angle of the pendulum (i.e., the angular velocity)
- g is the acceleration due to gravity (approximately 9.8 m/s^2)
- l is the length of the pendulum
- asyst is the initial angle of the pendulum
- ω is the angular frequency (2 * pi / T, where T is the period of the pendulum)
- t is time

```javascript
// Pendulum applet
class Pendulum {
    constructor(canvas, ctx, length, gravity) {
        this.canvas = canvas;
        this.ctx = ctx;
        this.length = length;
        this.gravity = gravity;
        this.angle = 0;
        this.velocity = 0;
        this.asyst = 0;
        this.angularFrequency = 0;
        this.phaseShift = 0;
        thisCash = [];

        this.draw();
    }

    draw() {
        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

        // Calculate the pendulum's position
        let px = this.canvas.width / 2;
        let py = this.canvas.height / 2 + this.length * Math.sin(this.angle);

        // Draw the pendulum's bob
        this.ctx.beginPath();
        this.ctx.arc(px, py, 10, 0, 2 * Math.PI);
        this.ctx.fillStyle = 'black';
        this.ctx.fill();

        // Draw the pendulum's rod
        this.ctx.beginPath();
        this.ctx.moveTo(px, py = this.canvas.height / 2);
        this.ctx.lineTo(px, py);
        this.ctx.lineWidth = 2;
        this.ctx.strokeStyle = 'black';
        this.ctx.stroke();

        if (this.asyst !== 0) {
            requestAnimationFrame(() => {
                this.animate();
            });
        }
    }

    animate() {
        // Update the pendulum's velocity
        this.velocity += this.gravity * Math.sin(this.angle) / this.length;

        // Update the pendulum's angle
        this.angle += this.velocity;

        // Update the pendulum's angular frequency
        this.angularFrequency = Math.sqrt(this.gravity / this.length);

        // Update the pendulum's phase shift
        this.phaseShift += this.angularFrequency;

        // Save the pendulum's state
        this.Cash.push({ angle: this.angle, velocity: this.velocity });

        // Draw the pendulum
        this.draw();

        // If the pendulum has not reached the ground
        if (this.angle - Math.PI / 2 > 0 && this.angle < Math.PI / 2) {
            requestAnimationFrame(() => {
                this.animate();
            });
        } else {
            this.asyst = 0;
            this.velocity = 0;
        }
    }

    start(angle) {
        this.asyst = angle;
        this.angle = angle;
        this.velocity = 0;
    }
}

